mapper.select:
SELECT YEAR(MAX(occurred_at)) AS year, MONTH(MAX(occurred_at)) AS month
FROM transactions
WHERE user_id = #{userId}

SELECT
    COALESCE(SUM(CASE WHEN type = 'INCOME'  THEN amount ELSE 0 END), 0) AS monthlyIncome,
    COALESCE(SUM(CASE WHEN type = 'EXPENSE' THEN amount ELSE 0 END), 0) AS monthlyExpense
FROM transactions
WHERE user_id = #{userId}
  AND YEAR(occurred_at) = #{year}
  AND MONTH(occurred_at) = #{month}
